package com.campusradar.accountdata;

import com.campusradar.common.*;
import com.campusradar.account.AuthRateLimits;
import com.campusradar.resume.PrivateFileStorage;
import com.campusradar.task.TaskService;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import org.springframework.stereotype.Service;
import static com.campusradar.common.SqlRows.map;

@Service
public class AccountDataService {
    private final SqlRows rows;private final OwnerTransactions owners;private final ContractInputs inputs;private final TaskService tasks;private final BackupCodec codec;private final PrivateFileStorage storage;private final Clock clock;private final PrivateSnapshot snapshots;
    public AccountDataService(SqlRows rows,OwnerTransactions owners,ContractInputs inputs,TaskService tasks,BackupCodec codec,PrivateFileStorage storage,Clock clock,PrivateSnapshot snapshots){this.rows=rows;this.owners=owners;this.inputs=inputs;this.tasks=tasks;this.codec=codec;this.storage=storage;this.clock=clock;this.snapshots=snapshots;}
    public Map<String,Object> revision(String owner){return rows.one("SELECT data_revision FROM users WHERE id=:u",Map.of("u",owner),Set.of(),Set.of());}
    private int current(String owner){return ((Number)revision(owner).get("dataRevision")).intValue();}
    void requireRecent(Long until){if(until==null||until<=clock.millis())throw new ApiProblem(403,"REAUTH_REQUIRED","请先重新输入密码验证身份，验证在十分钟内有效。");}
    private void revision(String owner,Object expected){if(current(owner)!=((Number)expected).intValue())throw new ApiProblem(409,"DATA_REVISION_CONFLICT","私人数据已变化，请刷新后重新预览或确认。");}
    public Object export(String owner,Map<String,Object> body,String key){inputs.validate("ExportInput",body);codec.ensureConfigured();return owners.write(owner,"POST","/api/v1/account/exports",key,body,202,false,()->{var p=map("u",owner,"since",Timestamp.from(clock.instant().minus(Duration.ofDays(1))));if(rows.db.queryForObject("SELECT COUNT(*) FROM tasks WHERE user_id=:u AND type='DATA_EXPORT' AND created_at>:since",p,Integer.class)>=3){var oldest=rows.one("SELECT MIN(created_at) AS oldest FROM tasks WHERE user_id=:u AND type='DATA_EXPORT' AND created_at>:since",p,Set.of(),Set.of());long seconds=Duration.between(clock.instant(),Instant.parse(oldest.get("oldest").toString()).plus(Duration.ofDays(1))).getSeconds();throw new AuthRateLimits.Exceeded((int)Math.max(1,Math.min(86400,seconds)));}return tasks.enqueue(owner,"DATA_EXPORT",Map.of("includeFiles",body.get("includeFiles")),"export:"+owner+":"+UUID.randomUUID());});}
    BackupCodec.Archive archive(String owner,String fileId){var file=rows.one("SELECT storage_key,size_bytes,sha256 FROM files WHERE user_id=:u AND id=:id AND purpose='BACKUP' AND state='READY' AND (expires_at IS NULL OR expires_at>:now)",map("u",owner,"id",fileId,"now",Timestamp.from(clock.instant())),Set.of(),Set.of());return codec.decode(owner,storage.read(file.get("storageKey").toString(),((Number)file.get("sizeBytes")).longValue(),file.get("sha256").toString()));}
    public Object preview(String owner,Map<String,Object> body,String key){inputs.validate("ImportInput",body);String fileId=body.get("fileId").toString();var file=rows.one("SELECT sha256 FROM files WHERE user_id=:u AND id=:id AND purpose='BACKUP' AND state='READY' AND (expires_at IS NULL OR expires_at>:now)",map("u",owner,"id",fileId,"now",Timestamp.from(clock.instant())),Set.of(),Set.of());List<String> issues;int files=0,records=0;Instant expiry=clock.instant().plus(Duration.ofMinutes(30));try{var archive=archive(owner,fileId);issues=snapshots.validate(owner,archive);files=((List<?>)archive.manifest().get("files")).size();if(issues.isEmpty())records=snapshots.recordCount(archive);Instant backupExpiry=Instant.parse(archive.manifest().get("expiresAt").toString());if(backupExpiry.isBefore(expiry))expiry=backupExpiry;}catch(ApiProblem e){if(e.status()!=422)throw e;issues=List.of(e.getMessage());}
        var summary=map("fileCount",files,"recordCount",records,"issues",issues,"backupSha256",file.get("sha256"));Instant expires=expiry;return owners.write(owner,"POST","/api/v1/account/import-previews",key,body,201,false,()->{String id=UUID.randomUUID().toString();var p=map("u",owner,"id",id,"file",fileId,"revision",current(owner),"state",((List<?>)summary.get("issues")).isEmpty()?"VALID":"INVALID","manifest",rows.json.writeValueAsString(summary),"expires",Timestamp.from(expires));rows.db.update("INSERT INTO import_previews(id,user_id,backup_file_id,data_revision,state,manifest,expires_at) VALUES(:id,:u,:file,:revision,:state,:manifest,:expires)",p);return preview(owner,id);});}
    @SuppressWarnings("unchecked") private Map<String,Object> preview(String owner,String id){var p=rows.one("SELECT id,state,data_revision,manifest,expires_at FROM import_previews WHERE user_id=:u AND id=:id",map("u",owner,"id",id),Set.of("manifest"),Set.of());var summary=(Map<String,Object>)p.remove("manifest");p.put("fileCount",summary.get("fileCount"));p.put("recordCount",summary.get("recordCount"));p.put("issues",summary.get("issues"));return p;}
    public Object apply(String owner,String previewId,Map<String,Object> body,String key,Long reauthUntil){requireRecent(reauthUntil);inputs.validate("ImportApply",body);return owners.write(owner,"POST","/api/v1/account/import-previews/"+previewId+"/apply",key,body,202,false,()->{
        var p=map("u",owner,"id",previewId);var preview=rows.one("SELECT state,data_revision,expires_at FROM import_previews WHERE user_id=:u AND id=:id",p,Set.of(),Set.of());if(!"VALID".equals(preview.get("state"))||!Instant.parse(preview.get("expiresAt").toString()).isAfter(clock.instant()))throw new ApiProblem(409,"PREVIEW_EXPIRED","恢复预览无效或已过期，请重新上传并预览。");revision(owner,body.get("dataRevision"));if(((Number)preview.get("dataRevision")).intValue()!=((Number)body.get("dataRevision")).intValue())throw new ApiProblem(409,"DATA_REVISION_CONFLICT","预览版本与确认版本不一致。");rows.db.update("UPDATE users SET data_operation='IMPORTING' WHERE id=:u",p);rows.db.update("UPDATE import_previews SET state='APPLYING',version=version+1 WHERE user_id=:u AND id=:id",p);return tasks.enqueue(owner,"DATA_IMPORT",map("previewId",previewId,"dataRevision",body.get("dataRevision")),"import:"+owner+":"+UUID.randomUUID());
    });}
    void purgeMutationReplays(String owner,String receiptRoute){rows.db.update("DELETE FROM idempotency_records WHERE user_id=:u AND (method<>'POST' OR route_hash<>:route)",map("u",owner,"route",owners.hash(receiptRoute)));}
    public Object reset(String owner,Map<String,Object> body,String key,Long reauthUntil){requireRecent(reauthUntil);inputs.validate("ResetInput",body);return owners.write(owner,"POST","/api/v1/account/reset",key,body,202,false,()->{revision(owner,body.get("dataRevision"));rows.db.update("UPDATE users SET data_operation='RESETTING' WHERE id=:u",Map.of("u",owner));return tasks.enqueue(owner,"USER_ERASURE",map("mode","PRIVATE_ONLY","dataRevision",body.get("dataRevision")),"reset:"+owner+":"+UUID.randomUUID());});}
    public Object erase(String owner,Map<String,Object> body,String key,Long reauthUntil){requireRecent(reauthUntil);inputs.validate("EraseInput",body);return owners.write(owner,"DELETE","/api/v1/me",key,body,202,false,()->{rows.db.update("UPDATE users SET status='DELETING',auth_version=auth_version+1,data_operation='RESETTING' WHERE id=:u",Map.of("u",owner));return tasks.enqueue(owner,"USER_ERASURE",Map.of("mode","ACCOUNT"),"erase:"+owner+":"+UUID.randomUUID());});}
}
